sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_progress;
uniform float amzp_amount;
uniform float amzp_gfps;
uniform float amzp_burst;
uniform float amzp_seed;
uniform float amzp_blockAmt;
uniform float2 amzp_blockSize;
uniform float amzp_blockShift;
uniform float amzp_lumaLoss;
uniform float amzp_lineAmt;
uniform float amzp_lineH;
uniform float amzp_lineShift;
uniform float amzp_lineColor;
uniform float amzp_stripeAmt;
uniform float amzp_stripeSize;
uniform float amzp_split;
uniform float amzp_advScale;
uniform float amzp_advAngle;
uniform float amzp_mixAmt;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float2 rot2(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float h1(float x) { return fract(sin(x * 78.233 + amzp_seed * 12.9898) * 43758.5453); }
    float h2(float2 p) { return fract(sin(dot(p, float2(12.9898, 78.233)) + amzp_seed * 7.17) * 43758.5453); }
    float tm() { return (amzp_autop>0.5) ? amzp_progress + time * amzp_autoSpeed : amzp_progress; }
    float4 at(float2 s) {
        if (!(amzp_overdrawOn>0.5)) s = 1.0 - abs(mod(s, 2.0) - 1.0);
        return amzTexture(0, l2s(s));
    }
    void amzRender() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 orig = amzTexture(0, amzScreenNorm());
        float t = tm();
        float frame = floor(t * max(amzp_gfps, 0.01));
        float on = step(h1(frame + 0.5), clamp(amzp_burst, 0.0, 1.0)) * clamp(amzp_amount, 0.0, 3.0);
        float k = max(amzp_advScale, 0.01);
        float aa = radians(amzp_advAngle);
        float2 gp = rot2((uv - 0.5) * W, -aa) / k;
        float2 ax = rot2(float2(1.0, 0.0), aa) / W;
        float2 cell = floor(gp / max(amzp_blockSize, float2(1.0)));
        float bh = h2(cell + frame * 1.234);
        float blk = step(bh, amzp_blockAmt * on);
        float row = floor(gp.y / max(amzp_lineH, 1.0));
        float lh = h2(float2(row, frame * 3.543));
        float lin = step(lh, amzp_lineAmt * on);
        float2 s = uv;
        if (blk > 0.0) s += (float2(h2(cell + 5.1 + frame), h2(cell + 9.3 + frame)) - 0.5) * 2.0 * amzp_blockShift * min(on, 1.0);
        if (lin > 0.0) s += ax * W.x * (h2(float2(row, frame + 7.7)) - 0.5) * 2.0 * amzp_lineShift * min(on, 1.0);
        float dmg = max(blk, lin);
        float2 d = ax * W.x * amzp_split * dmg * min(on, 1.0);
        float4 r = at(s + d), g = at(s), b = at(s - d);
        float4 c = float4(r.r, g.g, b.b, max(max(r.a, g.a), b.a));
        if (blk > 0.0) c.rgb = mix(c.rgb, c.ggg, clamp(amzp_lumaLoss, 0.0, 1.0));
        if (lin > 0.0) {
            float lum = dot(c.rgb, float3(1.0)) / 3.0;
            if (int(amzp_lineColor) == 0) c.rgb = float3(0.0, min(lum * 1.6, c.a), 0.0);
            else if (int(amzp_lineColor) == 1) {
                float ch = h2(float2(row, frame + 2.2));
                c.rgb = ch < 0.33 ? float3(c.r, 0.0, 0.0) : (ch < 0.66 ? float3(0.0, c.g, 0.0) : float3(0.0, 0.0, c.b));
            } else if (int(amzp_lineColor) == 2) c.rgb = c.a - c.rgb;
        }
        if (dmg > 0.0 && amzp_stripeAmt > 0.0 && h2(cell + row + frame * 0.37) < 0.7) {
            float st = fract(gp.y / max(amzp_stripeSize, 1.0));
            float3 mk = st < 0.333 ? float3(3.0, 0.0, 0.0) : (st < 0.666 ? float3(0.0, 3.0, 0.0) : float3(0.0, 0.0, 3.0));
            c.rgb = mix(c.rgb, min(c.rgb * mk, float3(c.a)), clamp(amzp_stripeAmt, 0.0, 1.0));
        }
        c = mix(orig, c, clamp(amzp_mixAmt, 0.0, 1.0));
        amzOutput = (amzp_overdrawOn>0.5) ? c : c * orig.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
